body.query:
query TaxonTypeSpecimens($from: Int, $size: Int, $predicate: Predicate) {
  occurrenceSearch(predicate: $predicate) {
    documents(from: $from, size: $size) {
      from
      size
      total
      results {
        key
        taxonKey
        originalUsageMatch {
          diagnostics {
            matchType
            confidence
          }

          usage {
            name
            key
          }
        }
        classification {
          usage {
            name
            rank
          }
        }
        typeStatus
        typifiedName
        catalogNumber
        recordedBy
        year
        country
        institutionCode
        collectionCode
        occurrenceID
        dataset {
          key
          title
        }
        extensions {
          dnaDerivedData
        }
      }
    }
  }
}
